# OSMIUM POLICY ENGINE
$script:OsmiumToolPolicies = @{ respond = @{ Risk = "None"; Approval = $false }; system_status = @{ Risk = "ReadOnly"; Approval = $false }; find_large_files = @{ Risk = "ReadOnly"; Approval = $false }; search_files = @{ Risk = "ReadOnly"; Approval = $false }; organise_preview = @{ Risk = "ReadOnly"; Approval = $false }; create_folder = @{ Risk = "Low"; Approval = $true } }
function Get-OsmiumToolPolicy { param([string]$Tool) if (-not $script:OsmiumToolPolicies.ContainsKey($Tool)) { throw "POLICY DENIED: Unknown tool: $Tool" }; return $script:OsmiumToolPolicies[$Tool] }
function Test-OsmiumToolPolicy { param([string]$Tool) try { $p=Get-OsmiumToolPolicy $Tool; [pscustomobject]@{Allowed=$true;Tool=$Tool;Risk=$p.Risk;RequiresApproval=$p.Approval;Reason="Registered"} } catch { [pscustomobject]@{Allowed=$false;Tool=$Tool;Risk="Unknown";RequiresApproval=$true;Reason=$_.Exception.Message} } }
function Confirm-OsmiumOperation { param([string]$Tool,[string]$Target="") $p=Get-OsmiumToolPolicy $Tool; if (-not $p.Approval) { return $true }; Write-Host "OSMIUM APPROVAL REQUIRED" -ForegroundColor Yellow; Write-Host "Operation: $Tool"; if ($Target) { Write-Host "Target: $Target" }; return ((Read-Host "Approve? (y/N)") -match "^(?i:y|yes)$") }